.forge-repertoire-starter{max-width:64rem;margin:auto}
.forge-orchestra-banner{position:relative;display:flex;align-items:end;min-height:clamp(12rem,34vw,22rem);overflow:hidden;border-radius:1rem;background:#173c43;color:white}
.forge-orchestra-banner img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center}
.forge-orchestra-banner img.image-top{object-position:center top}.forge-orchestra-banner img.image-bottom{object-position:center bottom}
.forge-orchestra-heading{position:relative;width:100%;padding:clamp(1rem,4vw,3rem);background:linear-gradient(transparent,#0b252be8);box-sizing:border-box}
.forge-orchestra-heading h1{margin:0;color:white;font-size:clamp(2rem,5vw,3.5rem);overflow-wrap:anywhere}.forge-orchestra-heading p:empty{display:none}
.forge-repertoire-starter nav{display:flex;flex-wrap:wrap;gap:.75rem;margin:1rem 0}.forge-repertoire-starter nav a,.forge-create-orchestra{padding:.7rem 1rem;border:1px solid #267266;border-radius:.6rem;color:inherit}
.forge-repertoire-fields{display:grid;gap:.65rem;margin:1rem 0}.forge-repertoire-fields label{display:grid;gap:.25rem}.forge-repertoire-fields input,.forge-repertoire-fields select,.forge-repertoire-fields textarea{box-sizing:border-box;width:100%}

"use strict";
const Importer=require("$:/plugins/huwiki/musescore-import/widget.js")["huwiki-ms-import"];
const repertoire=require("$:/plugins/huwiki/repertoire/model.js");
const orchestra="Repertoire/Orkestre/Start";
const destination="repertoire-import-orchestra";
function OrchestraImport(parseTreeNode,options){
 this.initialise(parseTreeNode,options);
}
OrchestraImport.prototype=Object.create(Importer.prototype);
OrchestraImport.prototype.createAbcFields=function(model,state,abc){
 const fields=Importer.prototype.createAbcFields.call(this,model,state,abc);
 fields[destination]=orchestra;
 return fields;
};
OrchestraImport.prototype.refresh=function(changes){
 const wiki=this.wiki;
 if(wiki.getTiddler(orchestra)?.fields["repertoire-kind"]==="orchestra"){
  Object.keys(changes).forEach(title=>{
   const score=wiki.getTiddler(title);
   if(score?.fields[destination]===orchestra&&score.fields["abc-source"]){
    repertoire.addItem(wiki,orchestra,title);
   }
  });
 }
 return Importer.prototype.refresh.call(this,changes);
};
exports["forge-orchestra-import"]=OrchestraImport;
